/* ---- !! REVISION v0.4 FRONT PANEL -- ADDED BY HAND !! --------------------
 *
 * The second PCB (2026-10-16) adds a front panel that the v0.3 netlist this
 * file was generated from does not know about, so gen_pinmap.py cannot emit
 * these lines yet.  They are correct as built; re-add them (or regenerate from
 * an exported v0.4 netlist) after any future regeneration, or the firmware
 * loses every front-panel control.
 *
 *   IO10 -> SA818 U5 pin 7   H/L, high/low RF power  (see PIN_SA818_HL)
 *   IO12 -> power LED        heartbeat, R5 1k, active HIGH  (= PIN_LED_STATUS)
 *   IO11 -> global RX LED    active HIGH, lit while receiving
 *   IO42 -> global TX LED    active HIGH, lit while the transmitter is keyed
 *   IO41 -> global PTT key   to GND, internal pull-up, active LOW
 *   IO38 -> VOL+ key         to GND, internal pull-up, active LOW
 *   IO39 -> VOL- key         to GND, internal pull-up, active LOW
 *   IO15 -> CH+ key          to GND, internal pull-up, active LOW  (remappable)
 *   IO16 -> CH- key          to GND, internal pull-up, active LOW  (remappable)
 *
 * The two volume keys were assigned the other way round at first (VOL+ = IO39)
 * and that was measurably wrong on the built panel: pressing the button on IO39
 * lowered the volume, so the silkscreen order does not match the layout order.
 * The aliases below now follow what the operator gets, which is what matters --
 * the netlist only knows the pin numbers, not which one is "+".
 *
 * All five keys are wired switch-to-GND with no external pull-up: the S3's
 * internal pull-up is what keeps them high when idle.  The three LEDs are
 * driven straight from the GPIO through their series resistors (no transistor,
 * no active-low sink), so "on" is level 1.  GPIO15/16 are on module pads 8/9
 * and were free on v0.3; GPIO38/39/41/42 are the module's JTAG pins, which is
 * fine because the S3 runs its USB-Serial/JTAG on GPIO19/20, not there.
 */
#define PIN_LED_RX                 GPIO_NUM_11
#define PIN_LED_TX                 GPIO_NUM_42
#define PIN_KEY_PTT                GPIO_NUM_41
#define PIN_KEY_VOL_UP             GPIO_NUM_39
#define PIN_KEY_VOL_DN             GPIO_NUM_38
#define PIN_KEY_CH_UP              GPIO_NUM_15
#define PIN_KEY_CH_DN              GPIO_NUM_16

/* ---- !! I2S NAMING TRAP !! ----------------------------------------
 * On THIS board the I2S nets are named from the CODEC's point of view,
 * which is the OPPOSITE of ESP-IDF's std-I2S naming:
 *
 *   net I2S_DIN  (GPIO7 -> ES8311 pin 9 DSDIN) = S3 -> codec
 *        -> ESP-IDF field  .dout = PIN_I2S_DIN
 *   net I2S_DOUT (GPIO8 <- ES8311 pin 7 ASDOUT) = codec -> S3
 *        -> ESP-IDF field  .din  = PIN_I2S_DOUT
 *
 * Swap them and you get silence with no build error.  These aliases
 * exist so the firmware reads correctly at the call site. */
#define PIN_I2S_TO_CODEC    PIN_I2S_DIN   /* = .dout */
#define PIN_I2S_FROM_CODEC  PIN_I2S_DOUT  /* = .din  */

/* ---- polarity / notes from the build reports ---- */
/* ESP32-S3-WROOM-1-N16R8: 16 MB flash + 8 MB OCT (OPI) PSRAM.   */
/*   -> GPIO35/36/37 are consumed by the OPI PSRAM and are NC here. */
/* U4 = LM4871 (net AMP_SHDN, GPIO13): SHUTDOWN IS ACTIVE-HIGH and R14
 * pulls it up, so the amplifier is OFF from power-up until the firmware
 * drives PIN_AMP_SHDN LOW.  (Polarity is REVERSED vs the old AW8737.) */
/* U5 = SA818S (net SA818_PTT, GPIO21): PTT is active-low and R15 pulls it
 * HIGH, so the radio sits in RX (safe) from power-up; only the firmware
 * may drive it low, and it must do so only from the PTT state machine. */
/* LED1 (net LED_STATUS, GPIO12) -> R5 1k -> LED -> GND: active HIGH. */
/* Native USB (USB-Serial/JTAG) is on GPIO19/20 -> flashing through the
 * J1 Type-C connector needs no USB-UART bridge and no button press. */
/* RX audio from the radio (SA818 pin 3 AF_OUT) is sampled by the S3's own
 * ADC on GPIO1 = ADC1_CH0, NOT through the ES8311.  TX audio (ES8311
 * DAC_P) is shared: R13 10k -> LM4871, and R16/R17 divider -> SA818 MIC. */

